function visitHTML(v){const p=place(v.placeId),stars=`<span class="stars" role="img" aria-label="${E(t('visit.rating',{n:v.rating}))}">${[1,2,3,4,5].map(n=>I(n<=v.rating?'star-fill':'star')).join('')}</span>`;return `<article class="visit-card"><div class="visit-top"><span class="visit-thumb brand-art tone-${[0,2,3][tone(v.placeId)%3]}" aria-hidden="true">${I(catIcon(p))}</span><div class="visit-meta"><a href="#place/${E(v.placeId)}"><h3>${E(p?nm(p):v.placeId)}</h3></a><p><time datetime="${E(v.date)}">${E(v.date)}</time>${v.rating?stars:`<span>${E(t('visit.noRating'))}</span>`}</p></div><div class="visit-menu"><button class="icon-button small" data-edit-visit="${E(v.id)}" aria-label="${E(t('visit.edit'))}">${I('pencil-simple')}</button><button class="icon-button small" data-delete-visit="${E(v.id)}" aria-label="${E(t('visit.delete'))}">${I('trash')}</button></div></div><p class="record-note">${E(v.note||t('visit.noNote'))}</p><div class="visit-actions"><button class="button subtle small" data-visit-photos="${E(v.id)}">${I('camera')}${E(t('visit.photos'))}</button><button class="button subtle small" data-save="${E(v.placeId)}">${db.saved.includes(v.placeId)?I('heart-fill')+E(t('visit.savedAgain')):I('heart')+E(t('visit.saveAgain'))}</button></div></article>`}
function journalPage(){const visits=[...db.visits].sort((a,b)=>b.date.localeCompare(a.date)),legacy=Object.values(db.legacyVisits).reduce((a,b)=>a+b,0),months=new Map();for(const v of visits){const k=v.date.slice(0,7);if(!months.has(k))months.set(k,[]);months.get(k).push(v)}return `<header class="page-head with-action"><div><h1 class="large-title">현장 기록</h1><p class="page-sub">빛을 본 순간의 시선과 질문을 남겨요.</p></div><button class="button head-action" data-new-visit>${I('plus')}방문 기록</button></header><div class="stat-strip">${[[visits.length,'방문 기록'],[new Set(visits.map(v=>v.placeId)).size,'기록한 장소'],[db.routes.length,'답사 코스'],...(legacy?[[legacy,'이전 방문']]:[])].map(([n,t])=>`<div class="stat"><b>${fmt(n)}</b><span>${t}</span></div>`).join('')}</div><div class="journal-tools"><button class="button subtle small" data-export-visits ${visits.length?'':'disabled'}>${I('download-simple')}기록 CSV</button><a class="button subtle small" href="#settings">${I('upload-simple')}백업 · 복원</a></div>${visits.length?[...months].map(([k,vs])=>`<section class="month-group"><h2 class="month-head">${k.slice(0,4)}년 ${Number(k.slice(5))}월</h2>${vs.map(visitHTML).join('')}</section>`).join(''):empty('첫 관찰을 남겨보세요','관람 날짜와 메모로 나만의 빛 아카이브를 시작하세요.')}<button class="fab" data-new-visit aria-label="방문 기록 추가">${I('plus')}<span aria-hidden="true">기록</span></button>`}
function calendarPage(){const today=C.today(),start=p=>C.validDate(p.program_start)?p.program_start:p.program_end,all=allPlaces().filter(p=>p.content_type!=='permanent'&&(C.validDate(p.program_start)||C.validDate(p.program_end))).sort((a,b)=>start(a).localeCompare(start(b))),live=all.filter(p=>X.status(p,today)!=='ended'),past=all.filter(p=>X.status(p,today)==='ended').reverse(),plans=db.routes.filter(r=>r.date).sort((a,b)=>a.date.localeCompare(b.date)),block=(d,cls='')=>C.validDate(d)?`<span class="date-block${cls}"><b>${Number(d.slice(8))}</b><small>${Number(d.slice(5,7))}월</small></span>`:'<span class="date-block unknown"><b>?</b><small>미정</small></span>',S={ongoing:['ok','진행 중'],upcoming:['info','개막 예정'],ended:['off','종료'],unknown:['off','일정 확인 필요']},row=p=>{const [tone,label]=S[X.status(p,today)]||S.unknown;return `<div class="calendar-row">${block(start(p))}<div class="calendar-text"><a href="#place/${E(p.place_id)}"><h3>${E(p.name_kr)}</h3></a><p>${E(p.current_program||'프로그램명 미확인')}</p><p class="tnum">${E(p.program_start||'시작 미확인')} – ${E(p.program_end||'종료 미확인')}</p><div class="pill-row"><span class="pill ${tone}">${label}</span></div>${link(official(p),'공식 안내')}</div></div>`},months=new Map();for(const p of live){const k=start(p).slice(0,7);if(!months.has(k))months.set(k,[]);months.get(k).push(p)}const years=new Set([...months.keys()].map(k=>k.slice(0,4))),ml=k=>(years.size>1?k.slice(2,4)+'년 ':'')+Number(k.slice(5))+'월';return `<header class="page-head"><h1 class="large-title">${E(t('calendar.h1'))}</h1><p class="page-sub">${E(t('calendar.sub'))}</p></header><section class="home-section first"><div class="section-head"><h2>나의 답사</h2><a class="text-link" href="#routes">코스 관리${I('caret-right')}</a></div>${plans.map(r=>`<a class="calendar-row${r.date<today?' past':''}" href="#route/${E(r.id)}">${block(r.date,r.date<today?' muted':'')}<div class="calendar-text"><h3>${E(r.name)}</h3><p class="tnum">${r.stops.length}곳 · ${E(r.date)}${r.date<today?' · 지난 답사':''}</p></div>${I('caret-right','row-chev')}</a>`).join('')||`<div class="section-empty">코스에 답사 날짜를 정하면 이곳에 모여요. <a class="text-link" href="#routes">코스 보기${I('caret-right')}</a></div>`}</section><section class="home-section"><div class="section-head"><div><h2>전시·기간형 프로그램</h2><small>수록된 일정이에요 · 운영 여부와 휴관일은 공식 출처에서 확인하세요</small></div></div>${months.size>1?`<div class="chips month-strip" role="group" aria-label="월로 이동">${[...months].map(([k,l])=>`<button type="button" class="chip" data-scroll-to="month-${k}">${ml(k)}<span class="chip-count">${l.length}</span></button>`).join('')}</div>`:''}${[...months].map(([k,l])=>`<div class="month-group" id="month-${k}"><h3 class="month-head">${k.slice(0,4)}년 ${Number(k.slice(5))}월</h3>${l.map(row).join('')}</div>`).join('')||empty('지금 진행 중이거나 예정된 일정이 없어요','상설 장소에는 종료일을 임의로 붙이지 않아요.')}${past.length?`<details class="past-list"><summary>종료된 프로그램 ${past.length}개</summary>${past.map(row).join('')}</details>`:''}</section>`}
// Settings: display, the visitor's own data, the app, the data behind the archive in plain words, privacy and legal.
