function videosOf(p){const v=window.AOLDataset?.videos;return v?[...(v(p.place_id)||[]),...(p.archive_place_id?v(p.archive_place_id)||[]:[])]:[]}
function detailLoading(p){const ld=window.AOLDataset?.loading;return !!ld&&(ld(p.place_id)||!!p.archive_place_id&&ld(p.archive_place_id))}
// Coordinates on the page: the place's own (any source that passes the map rule) or the live photo sync's Wikidata ones.
function coordsOf(p){if(X.mappable(p)||C.coords(p)&&!isArchive(p)&&!isSynced(p))return C.coords(p);const i=window.AOL_LIVE?.info?.[p.place_id];return i?.coord&&Number.isFinite(i.coord.lat)&&Number.isFinite(i.coord.lon)?[i.coord.lat,i.coord.lon]:null}
function mapLinkFor(p){const c=coordsOf(p);return c?`https://www.openstreetmap.org/?mlat=${c[0]}&mlon=${c[1]}#map=16/${c[0]}/${c[1]}`:''}
