function figureHTML(p,m,tag=''){const tier=tierOf(m),cap=m.caption_i18n?.[uiLang()]||m.caption||'',w=widest(m),prov=providerName(m);return `<figure class="gallery-figure${tier===4?' context':''}" data-tier="${tier}"><a class="gallery-photo" href="${E(C.safeURL(m.full_url)||mediaURL(m))}" target="_blank" rel="noopener noreferrer"${w?` style="--natural:${w}px"`:''}>${imgTag(m,nm(p)+(tier===4?' · '+t('photo.contextTag'):''),{cls:'photo',sizes:'(min-width:1024px) 36vw, (min-width:600px) 50vw, 100vw',base:960,low:true,type:phType(p),glyph:phGlyph(p)})}</a><figcaption>${tag||tier===4?`<span class="role-tag">${E(tag||t('photo.contextTag'))}</span>`:''}<b class="credit-line">© ${E(m.creator||t('photo.authorCheck'))} · ${E(m.license_code||'')}</b>${prov||m.rights_holder?`<span class="credit-source">${[prov?E(t('photo.via',{p:prov})):'',m.rights_holder&&m.rights_holder!==m.creator?E(t('photo.rightsHolder',{n:m.rights_holder})):''].filter(Boolean).join(' · ')}</span>`:''}${cap||m.captured_at?`<span>${[m.captured_at?E(t('photo.taken',{v:m.captured_at})):'',E(cap)].filter(Boolean).join(' · ')}</span>`:''}<span class="figure-links">${link(m.source_url,t('photo.original'))}${link(m.license_url,t('photo.terms'))}</span></figcaption></figure>`}
// Videos play inline only where the page's security policy allows media from their host (media-src, else default-src);
