// Official site first, then every source with its publisher; a link known to be broken is named but not linked.
function kindLabel(k){return !k?'':k==='official'?t('sources.official'):k==='encyclopedia'?t('sources.encyclopedia'):k==='commons'?'Wikimedia Commons':T.valid('source_kind',k)?vlabel('source_kind',k):''}
function linksSection(p){const seen=new Set(),items=[],add=(url,title,publisher,kind,broken)=>{const u=C.safeURL(url);if(!u||seen.has(u))return;seen.add(u);items.push({u,title,publisher,kind,broken})},web=p.official_url||p.website,i=window.AOL_LIVE?.info?.[p.place_id],src=sourcesOf(p),same=web&&src.find(s=>C.safeURL(s.url)===C.safeURL(web));if(web)add(web,same?.title||null,same?.publisher||null,'official',p.update_status==='link_broken'||same?.link_state==='broken');for(const s of src)add(s.url,s.title,s.publisher,s.kind,s.link_state==='broken');if(i?.website)add(i.website,null,null,'official');if(/^Q\d+$/.test(i?.qid||''))add('https://www.wikidata.org/wiki/'+i.qid,i.matchKind==='host'&&i.matchedName?t('live.host',{name:i.matchedName}):'Wikidata '+i.qid,'Wikidata','wikidata');if(i?.commonsCategory)add('https://commons.wikimedia.org/wiki/Category:'+encodeURIComponent(String(i.commonsCategory).replace(/ /g,'_')),t('live.commons'),'Wikimedia Commons',null);
 const host=u=>{try{return new URL(u).host.replace(/^www\./,'')}catch{return ''}};return `<section class="detail-section" id="detailSources"><h2>${E(t('sources.title'))}</h2>${items.length?`<ul class="source-list">${items.map(x=>`<li class="source-item${x.broken?' broken':''}"><div class="source-head"><b>${E(x.publisher||x.title||host(x.u))}</b>${kindLabel(x.kind)?`<span class="pill">${E(kindLabel(x.kind))}</span>`:''}</div>${x.title&&x.title!==x.publisher?`<p class="source-title">${E(x.title)}</p>`:''}${x.broken?`<p class="link-broken">${I('link-break','icon-sm')}${E(t('sources.broken'))} · ${E(host(x.u))}</p>`:link(x.u,host(x.u)||t('sources.open'))}</li>`).join('')}</ul>`:`<p class="section-empty">${E(t('sources.none'))}</p>`}</section>`}
// The location: a map loaded only when asked (the tiles come from OpenStreetMap), or an honest address search.
function mapSection(p){const c=coordsOf(p),osm=mapLinkFor(p);if(!c)return p.address?`<section class="detail-section" id="detailMap"><h2>${E(t('detail.location'))}</h2><p class="map-address"${uiLang()==='en'?' lang="ko"':''}>${E(p.address)}</p><div class="actions">${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.address),t('detail.searchAddress'),'button subtle source-link')}</div></section>`:'';return `<section class="detail-section" id="detailMap"><h2>${E(t('detail.location'))}</h2><div class="mini-map" id="miniMap" data-lat="${c[0]}" data-lng="${c[1]}"><div class="mini-map-preview"><span class="mini-pin" aria-hidden="true">${I('map-pin')}</span><button type="button" class="button" data-mini-map>${I('map-trifold')}${E(t('map.load'))}</button><p class="mini-note">${E(t('detail.mapNote'))}</p></div></div><p class="map-coords"><span class="tnum">${E(c[0].toFixed(5)+', '+c[1].toFixed(5))}</span>${placeLine(p)?' · '+E(placeLine(p)):''}</p><div class="actions">${link(osm,t('project.osm'),'text-link')}</div></section>`}
// ===== Place page (v0.18, fifth brief): a slide gallery of the project's own photos and the title block on top (two
// columns on wide screens), then five tabs whose panels all stay in the page (hidden, so readers and crawlers still
// have them). Facts are only what a record states: a field without data reads 자료 없음 (확인 필요 when its value is
// marked unverified), grouped on one line per group; editors' interpretation is marked 편집 해설 with its source.
// Image roles (the pipeline's kind when it sends one, else derived from the tier and role): the gallery shows the
// project's own media and installation photos; architecture, technical and event photos wait behind 추가 자료 보기;
// portraits appear only with the credits; unverified photos never.
// (No top-level const or let in this part: render() runs before it is evaluated.) A photo without any tier (an
// editor-reviewed seed photo, a Wikidata item's own image) is the project's photo; one of the building the project is
// installed on (match_kind host) is architectural context.
function kindOf(m){if(['project_media','project_installation','architecture_context','technical_documentation','event_documentation','artist_portrait','unverified'].includes(m?.kind))return m.kind;const r=String(m?.role||'');if(r==='portrait'||r==='artist_portrait')return 'artist_portrait';if(m?.context||r==='context'||m?.raw_tier===5||m?.match_kind==='host')return 'architecture_context';if(!Number.isInteger(m?.tier))return 'project_media';const tier=tierOf(m);if(tier<=2)return 'project_media';if(tier===3)return typeof m.media_active==='number'&&m.media_active<30?'architecture_context':'project_installation';return 'architecture_context'}
function galleryOf(p){const all=photos(p),by=k=>all.filter(m=>kindOf(m)===k),main=['project_media','project_installation'].flatMap(by),big=main.findIndex(m=>fits(m,'lead'));if(big>0)main.unshift(...main.splice(big,1));return {main,extra:['architecture_context','technical_documentation','event_documentation'].flatMap(by)}}
function portraitsOf(p){return mediaFor(p).filter(m=>kindOf(m)==='artist_portrait')}
function dpTabs(){return ['overview','architecture','art','visit','sources']}
function dpTab(){const x=pagePath()[2];return dpTabs().includes(x)?x:'overview'}
// The slider's state for the project on screen: the current photo and whether 추가 자료 is open.
function dpS(){return dpS.v||(dpS.v={id:'',index:0,extra:false})}
function reducedMotion(){return !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches}
