// ===== Sponsor slot (docs/BUSINESS.md §7) =====
// Nothing unless config.js turns SPONSORS on and data/sponsors.json exists (no request while it is off). With it: at most one slot per page, labelled 후원 or 광고, below the main content,
// never in a gallery, on the place pages and the research data page only, and on a place page only when every photo it
// shows may be used commercially (commercial_safe: no KOGL type 2 or 4, no NC licence, no unconfirmed rights).
// sponsors.json: {"slots":[{"label":"sponsor"|"ad","title","text"?,"url":"https://…","link"?,"pages"?:["place","data"],
// "from"?:"YYYY-MM-DD","until"?:"YYYY-MM-DD"}]}
function sponsorData(){const s=sponsorData.v||(sponsorData.v={status:'idle',slots:[]});if(s.status==='idle'){if(typeof fetch!=='function'||window.AOL_CONFIG?.SPONSORS!==true){s.status='none';return s}s.status='loading';fetch('data/sponsors.json',{cache:'no-cache'}).then(r=>r.ok?r.json():null).then(j=>{s.slots=sponsorValid(j);s.status='ok';if(s.slots.length)softRender()},()=>{s.status='none'})}return s}
