// What a licence allows (the pipeline's rightsUse): a photo is safe for a commercial page only when its use is known to
// be allowed.
function commercialOK(m){if(m?.commercial_use===true)return true;if(m?.commercial_use===false)return false;const k=Number(m?.kogl_type),l=String(m?.license_code||m?.license||'');if(k)return k===1||k===3;const kk=/KOGL Type ([1-4])/i.exec(l);if(kk)return kk[1]==='1'||kk[1]==='3';if(/\bNC\b|non-?commercial/i.test(l))return false;return /^(CC0|PD|public domain|CC BY(-SA)?\b)/i.test(l)||/^(cc-?zero|pdm)/i.test(l)}
