function dataPage(){if(indexPending())return `<header class="page-head"><h1 class="large-title">${E(t('data.title'))}</h1><p class="page-sub">${E(t('data.sub'))}</p></header>${loadingResults()}`;const ps=results(),st=X.stats(ps),onMap=ps.filter(X.mappable).length,photos=ps.filter(p=>mediaFor(p).length).length,countries=st.country.rows.length,lab=name=>k=>vlabel(name,k),L=uiLang();
 return `<header class="page-head"><h1 class="large-title">${E(t('data.title'))}</h1><p class="page-sub">${E(t('data.sub'))}</p></header><section class="data-scope"><p class="data-scope-line"><b>${E(whereLabel())}</b> · ${E(t('results.count',{n:fmt(ps.length)}))}</p>${activeChips()}<a class="text-link" href="#explore">${I('sliders-horizontal')}${E(t('data.changeFilters'))}${I('caret-right')}</a></section><div class="stat-strip data-stats">${[[ps.length,t('data.total')],[countries,t('data.countries')],[onMap,t('data.onMap')],[photos,t('data.withPhoto')]].map(([n,l])=>`<div class="stat"><b>${fmt(n)}</b><span>${E(l)}</span></div>`).join('')}</div>
 <section class="data-section" aria-labelledby="statsTitle"><div class="section-head"><div><h2 id="statsTitle">${E(t('data.stats'))}</h2><small>${E(t('data.statsSub'))}</small></div></div><div class="chart-grid">${barChart('chartRegion',t('facet.region'),st.region.rows,lab('region'),st.region)}${barChart('chartCountry',t('data.countryTop'),st.country.rows,countryName,{...st.country,limit:20})}${barChart('chartDecade',t('data.decade'),st.decade.rows,k=>t('data.decadeLabel',{v:k}),{...st.decade,note:t('data.yearNote')})}${barChart('chartType',t('facet.project_type'),st.project_type.rows,lab('project_type'),st.project_type)}${st.installation_method.rows.length?barChart('chartMethod',t('facet.installation_method'),st.installation_method.rows,lab('installation_method'),st.installation_method):''}${st.technology.rows.length?barChart('chartTech',t('facet.technology'),st.technology.rows,lab('technology'),{...st.technology,note:t('data.multiNote')}):''}</div>${st.year.rows.length?`<details class="year-details"><summary>${E(t('data.byYear'))}</summary>${barChart('chartYear',t('data.byYear'),st.year.rows,k=>String(k),st.year)}</details>`:''}</section>
 ${researchPublic()}${researchMember()}<section class="data-section" id="dataExport" aria-labelledby="exportTitle"><h2 id="exportTitle">${E(t('data.export'))}</h2><p class="section-note">${E(t('data.exportSub',{n:fmt(ps.length)}))}</p><p class="notice">${I('info')}<span>${E(X.WARNING[L])}</span></p><div class="actions export-actions"><button type="button" class="button" data-export="csv">${I('download-simple')}${E(t('data.csv'))}</button><button type="button" class="button tonal" data-export="json">${I('download-simple')}${E(t('data.json'))}</button></div><p class="section-note">${E(t('data.exportFormat'))}</p><details class="research-details dictionary"><summary>${E(t('data.dictionary'))}</summary><div class="table-scroll" tabindex="0" role="region" aria-label="${E(t('data.dictionary'))}"><table class="dict-table"><thead><tr><th scope="col">${E(t('data.field'))}</th><th scope="col">${E(t('data.type'))}</th><th scope="col">${E(t('data.description'))}</th></tr></thead><tbody>${X.EXPORT_FIELDS.map(([f,ty,ko,en])=>`<tr><td><code>${E(f)}</code></td><td>${E(ty)}</td><td>${E(L==='en'?en:ko)}</td></tr>`).join('')}</tbody></table></div></details><h3 class="licence-title" id="licenceTitle">${E(t('data.licTitle'))}</h3><dl class="kv-list licence-list" aria-labelledby="licenceTitle"><div class="kv"><dt>Wikidata</dt><dd>${E(t('data.licWikidata'))}</dd></div><div class="kv"><dt>Wikimedia Commons</dt><dd>${E(t('data.licCommons'))}</dd></div><div class="kv"><dt>${E(t('data.licEditorialLabel'))}</dt><dd>${E(t('data.licEditorial'))}</dd></div><div class="kv"><dt>${E(t('tab.sources'))}</dt><dd>${E(t('data.licSources'))}</dd></div></dl></section>
 <section class="data-section methodology" id="methodology" aria-labelledby="methodTitle"><h2 id="methodTitle">${E(t('data.method'))}</h2>${['sources','updates','images','classify','limits'].map(k=>`<h3>${E(t('m.'+k))}</h3><p>${E(t('m.'+k+'Text'))}</p>`).join('')}<h3>${E(t('m.cite'))}</h3><p>${E(t('m.citeText'))}</p><blockquote class="citation" id="datasetCitation">${E(datasetCitation(ps.length))}</blockquote><div class="cite-actions"><button type="button" class="button tonal" data-copy-dataset>${I('copy')}${E(t('cite.copy'))}</button></div></section>${sponsorSlot(null)}`}


// The map shows exactly the explore results that have usable coordinates (X.mappable); the list under it, its count
// and the clusters come from this one list (pinned in qa/archive.spec.mjs and qa/v17-scale.spec.mjs).
// The map's two views (v0.18): 국내 (Korean results, framed on Korea) by default, and 세계 (every result, the world).
// The pins, the list under the map and its count all come from this one list.
const KOREA_BOUNDS=[[33.0,124.6],[38.7,130.95]];
function mapScoped(){const r=results(allPlaces());return mapScope==='korea'?r.filter(X.isKR):r}
function mapProjects(){return mapScoped().filter(X.mappable)}
function mapScopeSwitch(){return `<div class="segmented map-scope" role="radiogroup" aria-label="${E(t('map.scope'))}">${['korea','world'].map(k=>`<button type="button" role="radio" aria-checked="${mapScope===k}" tabindex="${mapScope===k?0:-1}" data-map-scope="${k}">${I(k==='korea'?'buildings':'globe-hemisphere-east')}<span>${E(t(k==='korea'?'map.scope_korea':'map.scope_world'))}</span></button>`).join('')}</div>`}


function mapItem(p){const m=photoFor(p);return `<button class="map-list-item" data-map-select="${E(p.place_id)}"><span class="map-item-art">${m?imgTag(m,'',{sizes:'56px',max:330}):placeholder(p,'ph-small')}</span><span class="map-item-text"><b>${E(nm(p))}</b><small>${E([category(p),placeLine(p)].filter(Boolean).join(' · '))}</small></span>${I('caret-right','map-item-caret')}</button>`}
// The list under the map: the same filtered places as the pins (all of them, or those in view once the map moved).
function mapResultHTML(bounds,all=mapProjects()){if(indexPending())return `<div class="result-meta" aria-busy="true"><b>${E(t('results.loading'))}</b></div>`;const ps=bounds?all.filter(p=>bounds.contains([p.latitude,p.longitude])):all,shown=ps.slice(0,showCount),off=mapScoped().length-all.length;return `<div class="result-meta" data-count="${ps.length}" data-total="${all.length}"><b>${E(bounds?t('map.here'):mapScope==='korea'&&!filters.country?t('map.scope_korea'):whereLabel())} · ${E(t('results.count',{n:fmt(ps.length)}))}</b>${off?`<span class="map-off">${E(t('map.offMap',{n:fmt(off)}))} <a class="text-link" href="#explore">${E(t('map.toList'))}</a></span>`:''}</div>${shown.map(mapItem).join('')||empty(t('map.emptyTitle'),t('map.emptyBody'))}${ps.length>shown.length?`<button class="button subtle more-button" data-more>${E(t('results.more',{n:fmt(Math.min(PAGE,ps.length-shown.length))}))}</button>`:''}`}

function updateMapList(all){const el=$('#mapResults');if(el)el.innerHTML=mapResultHTML(currentMap&&mapFitted?currentMap.getBounds():null,all)}
// Grid clustering (smooth with thousands of places): the places in view, plus a margin, fall into square cells of the
// screen at the current zoom; a cell with one place is a dot on the shared canvas renderer, with more a numbered disc
// that zooms in on it. Projected positions are cached per zoom level and list; popups are built when opened.
let mapProj=null,mapFitted=false;
function mapPopup(p){return `<div class="map-pop"><p class="map-pop-eyebrow">${E(category(p))}</p><a href="#place/${E(p.place_id)}"><b>${E(nm(p))}</b> ${E(t('pop.details'))}${I('caret-right','icon-sm')}</a>${placeLine(p)?`<small>${E(placeLine(p))}</small>`:''}</div>`}
function drawMap(){if(!currentMap||!mapLayer)return;const z=currentMap.getZoom(),b=currentMap.getBounds().pad(.3),size=(window.innerWidth||1024)<768?52:60,ps=mapShown,cells=new Map();if(!mapProj||mapProj.z!==z||mapProj.ps!==ps)mapProj={z,ps,pts:ps.map(p=>currentMap.project([p.latitude,p.longitude],z))};ps.forEach((p,i)=>{if(!b.contains([p.latitude,p.longitude]))return;const q=mapProj.pts[i],k=Math.floor(q.x/size)+':'+Math.floor(q.y/size);let c=cells.get(k);if(!c)cells.set(k,c={ps:[],x:0,y:0});c.ps.push(p);c.x+=q.x;c.y+=q.y});mapLayer.clearLayers();mapMarkers=[];let sum=0,groups=0;
 for(const c of cells.values()){const n=c.ps.length;sum+=n;let m;if(n===1){const p=c.ps[0];m=L.circleMarker([p.latitude,p.longitude],{renderer:mapRenderer,radius:7,weight:2,color:'#FFFFFF',fillColor:'#6B52DE',fillOpacity:1});m.aolId=p.place_id;m.on('click',()=>{if(!m.getPopup())m.bindPopup(mapPopup(p));m.openPopup()})}else{groups++;const ll=currentMap.unproject([c.x/n,c.y/n],z),d=n<10?34:n<100?42:n<1000?50:58;m=L.marker(ll,{icon:L.divIcon({className:'map-cluster',html:`<span>${fmt(n)}</span>`,iconSize:[d,d]}),title:t('map.cluster',{n:fmt(n)}),alt:t('map.cluster',{n:fmt(n)}),keyboard:true});m.aolCount=n;m.aolIds=c.ps.map(p=>p.place_id);m.on('click',()=>{const bb=L.latLngBounds(c.ps.map(p=>[p.latitude,p.longitude]));if(bb.getNorthEast().equals(bb.getSouthWest())||z>=18)currentMap.setView(bb.getCenter(),Math.min(19,z+2));else currentMap.fitBounds(bb.pad(.2))})}mapLayer.addLayer(m);mapMarkers.push(m)}
 const el=$('#mapCanvas');if(el){el.dataset.points=String(sum);el.dataset.clusters=String(groups);el.dataset.total=String(ps.length)}}
// Places on the map: the explore results with usable coordinates (X.mappable). Typing is debounced; a background update
// that leaves the list as it was keeps the markers. When none of the new results is in view, the map frames them.
function updateMapResults(){clearTimeout(mapTimer);mapTimer=null;if(!$('#mapResults'))return;const ps=mapProjects();updateMapList(ps);refreshFilters();if(!currentMap||!mapLayer)return;if(ps.length===mapShown.length&&ps.every((p,i)=>p===mapShown[i]))return;mapShown=ps;const b=currentMap.getBounds();if(ps.length&&!ps.some(p=>b.contains([p.latitude,p.longitude])))fitMap();drawMap()}
function fitMap(){if(!currentMap)return;const ps=mapShown;if(mapScope==='korea'&&ps.length&&ps.every(X.isKR)){currentMap.fitBounds(KOREA_BOUNDS,{padding:[8,8],animate:false});mapFitted=true;return}if(ps.length){let s=90,w=180,n=-90,e=-180;for(const p of ps){if(p.latitude<s)s=p.latitude;if(p.latitude>n)n=p.latitude;if(p.longitude<w)w=p.longitude;if(p.longitude>e)e=p.longitude}currentMap.fitBounds([[s,w],[n,e]],{padding:[24,24],maxZoom:15,animate:false})}else currentMap.setView([25,10],2,{animate:false});mapFitted=true}

async function privatePhotos(visitId){if(!window.AOLCloud?.state.user){toast(t('private.signIn'));return}const uid=window.AOLCloud.state.user.id,el=modal(t('private.title'),`<p class="muted">${E(t('private.body'))}</p><input id="privatePhotoInput" type="file" accept="image/jpeg,image/png,image/webp" aria-label="${E(t('private.pick'))}"><div id="privatePhotoStatus" role="status"></div><div id="privatePhotoList"></div>`);const status=$('#privatePhotoStatus'),list=$('#privatePhotoList');const show=async()=>{const rows=await window.AOLCloud.photos.list(visitId);if(!el.open||window.AOLCloud.state.user?.id!==uid)return;list.innerHTML=rows.map(p=>`<figure><img class="photo" src="${E(C.safeURL(p.url))}" alt="${E(t('private.alt'))}"><button class="button danger small" data-private-delete="${E(p.id)}">${E(t('private.delete'))}</button></figure>`).join('')||`<p>${E(t('private.none'))}</p>`;list.querySelectorAll('[data-private-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(t('private.confirm')))return;try{await window.AOLCloud.photos.remove(b.dataset.privateDelete);await show()}catch(e){status.textContent=e.message}})};$('#privatePhotoInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;status.textContent=t('private.saving');try{await window.AOLCloud.photos.upload(visitId,file);await show();status.textContent=t('private.saved')}catch(e){status.textContent=e.message}e.target.value=''};try{await show()}catch(e){status.textContent=e.message}}

// One of four brand gradients per place, so a grid of places without photos does not repeat one box.
function tone(id){let h=0;for(const ch of String(id||''))h=(h*31+ch.charCodeAt(0))>>>0;return h%4}
function railNav(){return `<span class="rail-nav" hidden><button type="button" class="rail-btn" data-rail-step="-1" aria-label="${E(t('rail.prev'))}" disabled>${I('caret-left')}</button><button type="button" class="rail-btn" data-rail-step="1" aria-label="${E(t('rail.next'))}">${I('caret-right')}</button></span>`}
// Desktop rails are one row (3 or 4 cards) that scrolls sideways; the arrows show only when there is more to see.
function railState(){for(const r of document.querySelectorAll?.('.rail-scroll')||[]){const nav=r.closest('section')?.querySelector('.rail-nav');if(!nav)continue;const update=()=>{const max=r.scrollWidth-r.clientWidth;nav.hidden=max<8;const [prev,next]=nav.querySelectorAll('button');if(prev)prev.disabled=r.scrollLeft<8;if(next)next.disabled=r.scrollLeft>max-8};r.onscroll=update;update()}}

// Place page keys: arrows, Home and End move between the tabs; arrows change the photo in the gallery and the
// enlarged view (Esc closes the dialog natively). The current photo stays in place on resize and full screen.
document.addEventListener('keydown',e=>{const el=e.target;const tab=el?.closest?.('.dp-tabs [role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const all=[...tab.parentElement.querySelectorAll('[role=tab]')],i=all.indexOf(tab),n=all.length,j=e.key==='Home'?0:e.key==='End'?n-1:(i+(e.key==='ArrowLeft'?-1:1)+n)%n;all[j].focus();dpSelect(all[j].dataset.dpTab);return}
 if(!['ArrowLeft','ArrowRight'].includes(e.key))return;if($('#dpLightbox')?.open){e.preventDefault();dpLightbox(e.key==='ArrowLeft'?-1:1);return}const g=el?.closest?.('#detailPhotos');if(g&&!/^(INPUT|TEXTAREA|SELECT|VIDEO)$/.test(el.tagName)&&!el.closest('.dp-thumbs')){e.preventDefault();g.dpGo?.(dpS().index+(e.key==='ArrowLeft'?-1:1))}});
window.addEventListener('resize',()=>$('#detailPhotos')?.dpKeep?.(),{passive:true});
document.addEventListener('fullscreenchange',()=>requestAnimationFrame(()=>$('#detailPhotos')?.dpKeep?.()));

// ===== Error reports (fifth brief): for a photo or the page, with a reason and a note. Nothing changes by itself: the
// editors review each report. With the server configured (config.js) the report is stored in content_reports
// (insert-only for visitors); without it the dialog prepares a GitHub issue and an e-mail with the same text.
const REPORT_REASONS=['image_unrelated','person_image','low_quality','rights_or_credit','project_info','other'],REPORT_REPO='remona8787/remona8787.github.io';
function reportServer(){const c=window.AOL_CONFIG||{};return c.SUPABASE_URL&&c.SUPABASE_PUBLISHABLE_KEY?c:null}
function reportProjectId(p){const id=p?.dataset_id||p?.archive_dataset_id||p?.place_id||'';return /^[A-Za-z0-9_-]{2,40}$/.test(id)?id:''}
function reportDialog(placeId,imageId){const p=place(placeId);if(!p)return;const m=imageId?mediaFor(p).find(x=>x.provider_asset_id===imageId):null,server=!!(reportServer()&&reportProjectId(p)),signed=!!window.AOLCloud?.state?.user,reasons=imageId?REPORT_REASONS:['project_info','image_unrelated','person_image','low_quality','rights_or_credit','other'],mail=window.AOL_CONFIG?.SUPPORT_EMAIL||'remona56@hanmail.net';
 modal(t(imageId?'report.imageTitle':'report.pageTitle'),`<form class="report-form" id="reportForm" novalidate><p class="muted"><bdi>${E(nm(p))}</bdi>${m?' · '+E(creditText(m)):''}</p><fieldset class="report-reasons"><legend>${E(t('report.reason'))}</legend>${reasons.map((r,i)=>`<label class="radio-row"><input type="radio" name="reason" value="${r}"${i===0?' checked':''}><span>${E(t('report.r.'+r))}</span></label>`).join('')}</fieldset><label class="field"><span>${E(t('report.message'))}</span><textarea name="message" maxlength="2000" rows="4"></textarea></label>${server&&!signed?`<label class="field"><span>${E(t('report.email'))}</span><input type="email" name="email" maxlength="200" autocomplete="email"></label>`:''}<p class="section-note">${E(t('report.reviewNote'))}</p><div class="form-actions">${server?`<button type="submit" class="button">${E(t('report.send'))}</button>`:`<a class="button" id="reportIssue" href="https://github.com/${REPORT_REPO}/issues/new" target="_blank" rel="noopener noreferrer">${I('github-logo')}${E(t('report.github'))}</a><a class="button subtle" id="reportMail" href="mailto:${E(mail)}">${I('envelope-simple')}${E(t('report.mail'))}</a>`}</div><p class="report-status" role="status"></p></form>`);
 const f=$('#reportForm'),body=()=>{const fd=new FormData(f),r=String(fd.get('reason')||''),msg=String(fd.get('message')||'').trim();return {reason:REPORT_REASONS.includes(r)?r:'other',message:msg.slice(0,2000),email:String(fd.get('email')||'').trim()}};
 if(!server){const sync=()=>{const b=body(),title=`[${imageId?'image':'project'}] ${nm(p)}: ${t('report.r.'+b.reason)}`,text=[t('report.r.'+b.reason),'',`- ${t('report.project')}: ${nm(p)} (${p.dataset_id||p.place_id})`,`- ${t('report.url')}: ${recordURL(p)}`,m?`- ${t('report.photo')}: ${m.source_url||mediaURL(m)} (${creditText(m)})`:'',b.message?'\n'+b.message:''].filter(Boolean).join('\n'),gh=new URL(`https://github.com/${REPORT_REPO}/issues/new`);gh.searchParams.set('title',title);gh.searchParams.set('body',text);gh.searchParams.set('labels',imageId?'report,image':'report');$('#reportIssue').href=gh.href;$('#reportMail').href=`mailto:${mail}?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(text)}`};f.addEventListener('input',sync);f.addEventListener('change',sync);sync();return}
 f.onsubmit=async e=>{e.preventDefault();const b=body(),st=f.querySelector('.report-status'),btn=f.querySelector('[type=submit]');btn.disabled=true;st.textContent=t('report.sending');try{await sendReport({project_id:reportProjectId(p),image_id:imageId?String(imageId).slice(0,200):null,reason:b.reason,message:b.message||null,contact_email:!signed&&b.email?b.email.slice(0,200):null});st.textContent=t('report.sent');btn.remove()}catch{st.textContent=t('report.failed');btn.disabled=false}}}
// Signed in: the account's client (the row carries the reporter); otherwise PostgREST with the publishable key alone.
async function sendReport(row){const cloud=window.AOLCloud,user=cloud?.state?.user,client=user&&cloud.client?.();if(client){const {error}=await client.from('content_reports').insert({...row,contact_email:null,reporter:user.id});if(error)throw error;return}const c=reportServer(),res=await fetch(String(c.SUPABASE_URL).replace(/\/+$/,'')+'/rest/v1/content_reports',{method:'POST',headers:{apikey:c.SUPABASE_PUBLISHABLE_KEY,'content-type':'application/json',prefer:'return=minimal'},body:JSON.stringify(Object.fromEntries(Object.entries(row).filter(([,v])=>v!==null)))});if(!res.ok)throw Error('report_'+res.status)}
// ===== Research data (fifth brief): the public package of each build, and the member tier (docs/RESEARCH_DATA.md) =====
// 공개: data/research/latest.json names the package the deploy published (version = build id, data as of, files with
// size and SHA-256, the citation). Until it exists the page says so and the export of the current results stays.
// 회원: only when a server is configured (config.js): the catalogue is public; downloading needs a verified e-mail and
// a profile with the two consents; the Edge Function returns a short-lived signed link with the licence, citation and
// checksum. Without a server the page says the member tier is being prepared: no button that cannot work.
function researchPkg(){const s=researchPkg.v||(researchPkg.v={status:'idle',data:null});if(s.status==='idle'&&typeof fetch!=='function')s.status='missing';if(s.status==='idle'){s.status='loading';fetch('data/research/latest.json',{cache:'no-cache'}).then(r=>r.ok?r.json():null).then(j=>{s.data=researchValid(j);s.status=s.data?'ok':'missing'},()=>{s.status='missing'}).then(()=>{if(pagePath()[0]==='data')softRender()})}return s}
function researchValid(j){if(!j||typeof j!=='object')return null;const path=typeof j.path==='string'&&/^data\/research\/[A-Za-z0-9._-]{1,80}\/$/.test(j.path)?j.path:null,files=j.files&&typeof j.files==='object'?Object.entries(j.files).filter(([n,f])=>/^[A-Za-z0-9._-]{1,80}$/.test(n)&&f&&typeof f==='object').map(([n,f])=>({name:n,bytes:Number.isFinite(f.bytes)?f.bytes:null,sha256:typeof f.sha256==='string'&&/^[0-9a-f]{64}$/.test(f.sha256)?f.sha256:null})):[];if(!path||!files.length)return null;const str=(v,n=400)=>typeof v==='string'?v.slice(0,n):'';return {title:str(j.title,200),dataset:str(j.dataset,80),version:str(j.version,80),created:str(j.created,40),data_as_of:str(j.data_as_of,40),citation:str(j.citation,1200),path,files,counts:j.counts&&typeof j.counts==='object'?j.counts:null}}
function bytesText(n){if(!Number.isFinite(n))return '';const u=['B','KB','MB','GB'];let i=0,v=n;while(v>=1024&&i<u.length-1){v/=1024;i++}return (i?v.toFixed(v<10?1:0):String(v))+' '+u[i]}
function researchPublic(){const s=researchPkg(),head=`<h2 id="researchPublicTitle">${E(t('rd.public'))}</h2>`;if(s.status!=='ok')return `<section class="data-section" id="researchPublic" aria-labelledby="researchPublicTitle">${head}<p class="section-note"${s.status==='loading'?' aria-busy="true"':''}>${E(t(s.status==='loading'?'rd.loading':'rd.missing'))}</p></section>`;const d=s.data,counts=d.counts?Object.entries(d.counts).filter(([,v])=>Number.isFinite(v)).slice(0,6):[];
 return `<section class="data-section" id="researchPublic" aria-labelledby="researchPublicTitle">${head}<p class="data-scope-line"><b>${E(d.title||t('rd.package'))}</b> · ${E(t('rd.version',{v:d.version}))}${d.data_as_of?' · '+E(t('rd.asOf',{d:String(d.data_as_of).slice(0,10)})):''}</p>${counts.length?`<p class="section-note">${counts.map(([k,v])=>`${E(k)} ${fmt(v)}`).join(' · ')}</p>`:''}<p class="notice">${I('info')}<span>${E(t('rd.excluded'))}</span></p><div class="table-scroll" tabindex="0" role="region" aria-label="${E(t('rd.files'))}"><table class="dict-table rd-files"><thead><tr><th scope="col">${E(t('rd.file'))}</th><th scope="col">${E(t('rd.size'))}</th><th scope="col">SHA-256</th></tr></thead><tbody>${d.files.map(f=>`<tr><td><a href="${E(d.path+f.name)}" download>${I('download-simple','icon-sm')}<code>${E(f.name)}</code></a></td><td class="tnum">${E(bytesText(f.bytes))}</td><td>${f.sha256?`<code class="rd-sha" title="${E(f.sha256)}">${E(f.sha256.slice(0,16))}…</code>`:''}</td></tr>`).join('')}</tbody></table></div>${d.citation?`<h3>${E(t('m.cite'))}</h3><blockquote class="citation" id="researchCitation">${E(d.citation)}</blockquote><div class="cite-actions"><button type="button" class="button tonal" data-copy-research>${I('copy')}${E(t('cite.copy'))}</button></div>`:''}</section>`}
// The member tier's state for this visit: the catalogue, the profile and the downloads of the signed-in user.
function researchMemberState(){return researchMemberState.v||(researchMemberState.v={status:'idle',uid:null,catalog:[],versions:[],profile:undefined,downloads:[],result:null,error:'',busy:false})}
async function researchLoad(){const s=researchMemberState(),cloud=window.AOLCloud,client=cloud?.client?.();if(!client)return;const uid=cloud.state?.user?.id||null;if(s.status==='loading'||s.status==='ok'&&s.uid===uid)return;s.status='loading';s.uid=uid;try{const [ds,vs]=await Promise.all([client.from('research_datasets').select('id,title_ko,title_en,description_ko,tier,licence,licence_url').neq('tier','public'),client.from('research_dataset_versions').select('dataset_id,version,data_as_of,record_count,formats,sha256,changelog,citation').order('data_as_of',{ascending:false})]);if(ds.error||vs.error)throw ds.error||vs.error;s.catalog=ds.data||[];s.versions=vs.data||[];if(uid){const [pr,dl]=await Promise.all([client.from('research_profiles').select('user_id,display_name,affiliation,user_type,research_field,purpose,country_iso2').eq('user_id',uid).maybeSingle(),client.from('research_downloads').select('dataset_id,version,format,ok,error,requested_at').order('requested_at',{ascending:false}).limit(20)]);s.profile=pr.error?undefined:pr.data||null;s.downloads=dl.error?[]:dl.data||[]}else{s.profile=undefined;s.downloads=[]}s.status='ok'}catch{s.status='error'}if(pagePath()[0]==='data')softRender()}
function researchMember(){const head=`<h2 id="researchMemberTitle">${E(t('rd.member'))}</h2>`,wrap=x=>`<section class="data-section" id="researchMember" aria-labelledby="researchMemberTitle">${head}${x}</section>`;if(!reportServer())return wrap(`<p class="section-note">${E(t('rd.memberSoon'))}</p>`);
 const s=researchMemberState(),cloud=window.AOLCloud;if(!cloud?.client?.()||s.status==='idle'||s.status==='loading'){if(cloud?.client?.())researchLoad();return wrap(`<p class="section-note" aria-busy="true">${E(t('rd.loading'))}</p>`)}if(s.status==='error')return wrap(`<p class="section-note">${E(t('rd.memberError'))}</p>`);
 const user=cloud.state?.user,L=uiLang(),can=!!user&&!!s.profile,gate=!user?`<p class="notice">${I('info')}<span>${E(t('rd.signIn'))}</span> <a class="text-link" href="#account">${E(t('rd.signInLink'))}</a></p>`:!s.profile?researchProfileForm():'';
 const list=s.catalog.length?s.catalog.map(d=>{const vs=s.versions.filter(v=>v.dataset_id===d.id);return `<article class="rd-dataset"><h3>${E(L==='en'&&d.title_en||d.title_ko)}</h3>${d.description_ko?`<p>${E(d.description_ko)}</p>`:''}<p class="section-note">${E(t('rd.licence'))}: ${d.licence_url?link(d.licence_url,d.licence):E(d.licence)}${d.tier==='institution'?' · '+E(t('rd.institution')):''}</p>${vs.map(v=>`<div class="rd-version"><p><b>${E(t('rd.version',{v:v.version}))}</b> · ${E(t('rd.asOf',{d:v.data_as_of}))} · ${E(t('rd.records',{n:fmt(v.record_count)}))}</p>${d.tier==='member'?`<div class="actions">${(v.formats||[]).map(f=>`<button type="button" class="button tonal" data-rd-download="${E(d.id)}" data-rd-version="${E(v.version)}" data-rd-format="${E(f)}"${can&&!s.busy?'':' disabled'}>${I('download-simple')}${E(String(f).toUpperCase())}</button>`).join('')}</div>`:''}<details class="rd-meta"><summary>${E(t('rd.details'))}</summary><blockquote class="citation">${E(v.citation)}</blockquote>${Object.entries(v.sha256||{}).map(([f,h])=>`<p><code>${E(f)}</code> SHA-256 <code class="rd-sha">${E(String(h))}</code></p>`).join('')}${v.changelog?`<p>${E(v.changelog)}</p>`:''}</details></div>`).join('')}</article>`}).join(''):`<p class="section-note">${E(t('rd.noDatasets'))}</p>`;
 const r=s.result,result=r?`<div class="rd-result" role="status"><p><b>${E(t('rd.ready',{f:r.file_name||''}))}</b> ${link(r.url,t('rd.openLink'),'button')}</p><p class="section-note">${E(t('rd.expires',{n:Math.round((r.expires_in||300)/60)}))}</p><dl class="kv-list"><div class="kv"><dt>${E(t('rd.licence'))}</dt><dd>${r.licence_url?link(r.licence_url,r.licence||r.licence_url):E(r.licence||'')}</dd></div><div class="kv"><dt>${E(t('rd.asOfLabel'))}</dt><dd>${E(r.data_as_of||'')} · ${E(t('rd.records',{n:fmt(r.record_count||0)}))}</dd></div><div class="kv"><dt>SHA-256</dt><dd><code class="rd-sha">${E(r.sha256||'')}</code></dd></div></dl><blockquote class="citation" id="rdResultCitation">${E(r.citation||'')}</blockquote><button type="button" class="button tonal" data-copy-rd-result>${I('copy')}${E(t('cite.copy'))}</button></div>`:'';
 const err=s.error?`<p class="report-status" role="alert">${E(s.error)}</p>`:'';
 const mine=user&&s.downloads.length?`<details class="rd-mine"><summary>${E(t('rd.mine',{n:s.downloads.length}))}</summary><ul class="dp-list">${s.downloads.map(x=>`<li>${E(String(x.requested_at).slice(0,16).replace('T',' '))} · ${E(x.dataset_id)} ${E(x.version)} ${E(String(x.format).toUpperCase())} · ${E(x.ok?t('rd.ok'):t('rd.failed'))}</li>`).join('')}</ul></details>`:'';
 return wrap(`<p class="section-note">${E(t('rd.memberSub'))}</p>${gate}${list}${err}${result}${mine}`)}
function researchProfileForm(){const types=['researcher','student','professional','public','other'];return `<form class="rd-profile report-form" id="rdProfile"><h3>${E(t('rd.profileTitle'))}</h3><p class="section-note">${E(t('rd.profileSub'))}</p><label class="radio-row"><input type="checkbox" name="terms" required><span>${E(t('rd.consentTerms'))} <a href="./terms.html" target="_blank" rel="noopener">${E(t('rd.read'))}</a></span></label><label class="radio-row"><input type="checkbox" name="privacy" required><span>${E(t('rd.consentPrivacy'))} <a href="./privacy.html" target="_blank" rel="noopener">${E(t('rd.read'))}</a></span></label><fieldset class="rd-optional"><legend>${E(t('rd.optional'))}</legend><label class="field"><span>${E(t('rd.f.name'))}</span><input name="display_name" maxlength="80"></label><label class="field"><span>${E(t('rd.f.affiliation'))}</span><input name="affiliation" maxlength="160"></label><label class="field"><span>${E(t('rd.f.type'))}</span><select name="user_type"><option value="">${E(t('rd.none'))}</option>${types.map(x=>`<option value="${x}">${E(t('rd.type.'+x))}</option>`).join('')}</select></label><label class="field"><span>${E(t('rd.f.field'))}</span><input name="research_field" maxlength="120"></label><label class="field"><span>${E(t('rd.f.purpose'))}</span><textarea name="purpose" maxlength="500" rows="2"></textarea></label><label class="field"><span>${E(t('rd.f.country'))}</span><input name="country_iso2" maxlength="2" pattern="[A-Za-z]{2}" autocomplete="country"></label></fieldset><div class="form-actions"><button type="submit" class="button">${E(t('rd.saveProfile'))}</button></div></form>`}
async function researchSaveProfile(f){const s=researchMemberState(),cloud=window.AOLCloud,client=cloud?.client?.(),user=cloud?.state?.user;if(!client||!user)return;const fd=new FormData(f);if(!fd.get('terms')||!fd.get('privacy')){s.error=t('rd.consentNeeded');render();return}const opt=k=>{const v=String(fd.get(k)||'').trim();return v||null},country=opt('country_iso2');const row={user_id:user.id,terms_version:APP_VERSION,privacy_version:APP_VERSION,display_name:opt('display_name'),affiliation:opt('affiliation'),user_type:opt('user_type'),research_field:opt('research_field'),purpose:opt('purpose'),country_iso2:country&&/^[A-Za-z]{2}$/.test(country)?country.toUpperCase():null};const {error}=await client.from('research_profiles').upsert(row);if(error){s.error=t('rd.profileFailed');render();return}s.error='';s.status='idle';researchLoad()}
const RD_ERRORS={authentication_required:'rd.e.signIn',invalid_session:'rd.e.signIn',email_not_confirmed:'rd.e.email',profile_and_consent_required:'rd.e.profile',institution_agreement_required:'rd.e.institution',dataset_not_found:'rd.e.notFound',version_not_found:'rd.e.notFound',format_not_available:'rd.e.notFound',public_dataset_use_site:'rd.e.public',rate_limited:'rd.e.rate'};
async function researchDownload(dataset,version,format){const s=researchMemberState(),cfg=reportServer(),client=window.AOLCloud?.client?.();if(!cfg||!client||s.busy)return;s.busy=true;s.error='';s.result=null;render();try{const {data}=await client.auth.getSession(),token=data?.session?.access_token;if(!token)throw {code:'authentication_required'};const res=await fetch(String(cfg.SUPABASE_URL).replace(/\/+$/,'')+'/functions/v1/research-download',{method:'POST',headers:{authorization:'Bearer '+token,apikey:cfg.SUPABASE_PUBLISHABLE_KEY,'content-type':'application/json'},body:JSON.stringify({dataset,version,format})});const j=await res.json().catch(()=>({}));if(!res.ok||!j||!C.safeURL(j.url))throw {code:j?.error||(res.status===503?'unavailable':'failed')};s.result=j}catch(e){s.error=t(RD_ERRORS[e?.code]||'rd.e.unavailable')}s.busy=false;s.status='idle';researchLoad();render()}
document.addEventListener('submit',e=>{if(e.target?.id!=='rdProfile')return;e.preventDefault();researchSaveProfile(e.target)});
// Signing in or out changes what the member tier offers.
window.addEventListener('aol:cloud-state',()=>{const s=researchMemberState.v;if(s&&s.uid!==(window.AOLCloud?.state?.user?.id||null)&&s.status!=='loading')s.status='idle';if(pagePath()[0]==='data')softRender()});
